 "content": "def transform(grid):
    out = [row[:] for row in grid]
    bg = grid[0][0]
    h, w = len(grid), len(grid[0])

    # Row-end motif: duplicate the last foreground run into an equally sized blank suffix.
    for r, row in enumerate(grid):
        end = w - 1
        while end >= 0 and row[end] == bg:
            end -= 1
        if 0 <= end < w - 1:
            color = row[end]
            start = end
            while start > 0 and row[start - 1] == color:
                start -= 1
            if end - start + 1 == w - end - 1:
                for c in range(end + 1, w):
                    out[r][c] = 1

    # Column-end motif: analogous continuation vertically.
    for c in range(w):
        end = h - 1
        while end >= 0 and grid[end][c] == bg:
            end -= 1
        if 0 <= end < h - 1:
            color = grid[end][c]
            start = end
            while start > 0 and grid[start - 1][c] == color:
                start -= 1
            if end - start + 1 == h - end - 1:
                for r in range(end + 1, h):
                    out[r][c] = 1
    return out

def _check_shape(grid):
    out = transform(grid)
    assert 1 <= len(out) <= 30 and 1 <= len(out[0]) <= 30
    assert all(len(row) == len(out[0]) for row in out)
    assert all(type(v) is int and 0 <= v <= 9 for row in out for v in row)
    return out

if __name__ == '__main__':
    assert transform([[9,9,9,9],[9,9,9,9]]) == [[9,9,9,9],[9,9,9,9]]
    print('shape helper verified')
",
 "cross_profile": false
}

